    generateDownloadUrl: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Book ID to download */
                bookId: string;
            };
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": {
                    /** @description Optional device identifier */
                    deviceId?: string;
                };
            };
        };
        responses: {
            /** @description Download URL generated */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * Format: uri
                         * @description Pre-signed S3 URL (expires in 1 hour)
                         */
                        downloadUrl: string;
                        /**
                         * Format: date-time
                         * @description URL expiration time
                         */
                        expiresAt: string;
                        /** @description File size in bytes */
                        fileSize: number;
                    };
                };
            };
            /**
             * @description Audio file is in the S3 Intelligent-Tiering Archive Access tier; a
             *     restore was initiated (idempotent). Same shape as the stream
             *     endpoint's restoring response — retry the download after the
             *     restore completes.
             */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["BookStreamResponse"];
                };
            };
            /** @description Book has no audio file */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Book not found */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Download limit exceeded (10/day) */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Downloads require S3 configuration */
            501: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
